export function logoPalette(pixels){const bins=new Map();for(let i=0;i<pixels.length;i+=4){let[r,g,b,a]=pixels.slice(i,i+4);const max=Math.max(r,g,b),min=Math.min(r,g,b);if(a<180||max-min<30||max>248&&min>220||max<35)continue;const key=[r,g,b].map(v=>Math.round(v/32)).join(',');const x=bins.get(key)||[0,0,0,0];x[0]+=r;x[1]+=g;x[2]+=b;x[3]++;bins.set(key,x)}const colors=[...bins.values()].sort((a,b)=>b[3]-a[3]).map(x=>x.slice(0,3).map(v=>Math.round(v/x[3])));function accessible(rgb){let c=rgb.slice();const luminance=()=>c.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0);while(luminance()>.18)c=c.map(v=>Math.round(v*.92));return '#'+c.map(v=>v.toString(16).padStart(2,'0')).join('')}return colors.length?[accessible(colors[0]),accessible(colors.find(c=>Math.hypot(...c.map((v,i)=>v-colors[0][i]))>100)||colors[0])]:['#123747','#94763c']}
let generation=0;
export async function applyTenantTheme(t){const version=++generation;let palette=t?.code==='01'&&!t?.logo?['#397b9c','#ac508b']:['#123747','#94763c'];function apply(){if(version!==generation)return;const s=document.documentElement.style;s.setProperty('--green',palette[0]);s.setProperty('--pink',palette[1]);s.setProperty('--gold',palette[1]);s.setProperty('--soft-blue',palette[0]+'0d');document.querySelector('meta[name="theme-color"]')?.setAttribute('content',palette[0])}apply();if(!t?.logo)return;try{const i=new Image();i.src=t.logo;await i.decode();const c=document.createElement('canvas');c.width=c.height=64;const ctx=c.getContext('2d');ctx.drawImage(i,0,0,64,64);palette=logoPalette(ctx.getImageData(0,0,64,64).data);apply()}catch{}}
